// ART3D — a procgen 3D pack: custom geometries + composite spawners for the
// world3d layer, zero model files (the 3D twin of art2d — the pack shape a
// future MCP art block takes). Geometries are unit-sized triangle soups fed
// through `world.custom(name, gen, config)` — every crystal in a scene is
// ONE instanced draw, however many you place. Faceted shapes use FLAT
// face normals on purpose (crystals/rocks read as cut surfaces); the
// engine's Builder self-corrects winding.
//
//   const art = registerArt3d(world);
//   art.crystal({ x: 2, z: -4, color: '#7fd4ff', gloss: 0.9 });
//   art.tree({ x: -3, z: 2, scale: 1.4 });          // composite: trunk + canopy
//   art.crystalCluster({ x: 0, z: -8, count: 5 });  // scatter, deterministic

import type { World3d, Mesh3d, Mesh3dConfig } from '../lib/world3d.js';
import { Builder } from '../lib/geometry3d.js';

// Deterministic pseudo-random (procgen must not flicker between runs).
const rnd = (a: number, b = 0): number => {
  const s = Math.sin(a * 127.1 + b * 311.7) * 43758.5453;
  return s - Math.floor(s);
};

/**
 * Flat-shaded triangle with GUARANTEED outward facing. The trap this fixes:
 * deriving the normal from the winding makes the Builder's winding check
 * self-satisfying (a clockwise face gets an inward normal that "agrees"
 * with itself) — so outwardness must come from GEOMETRY: the face normal is
 * flipped to point away from `inside` (a point inside the shape), and the
 * Builder then corrects the winding to match. Every face renders from
 * every camera angle.
 */
function face(b: Builder, inside: number[], p1: number[], p2: number[], p3: number[]): void {
  const ux = p2[0] - p1[0], uy = p2[1] - p1[1], uz = p2[2] - p1[2];
  const vx = p3[0] - p1[0], vy = p3[1] - p1[1], vz = p3[2] - p1[2];
  let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
  const l = Math.hypot(nx, ny, nz);
  if (l < 1e-6) return;                    // degenerate (pole fans produce a==c tris)
  nx /= l; ny /= l; nz /= l;
  // Outward = away from the inside point (winding-independent truth).
  const cx = (p1[0] + p2[0] + p3[0]) / 3 - inside[0];
  const cy = (p1[1] + p2[1] + p3[1]) / 3 - inside[1];
  const cz = (p1[2] + p2[2] + p3[2]) / 3 - inside[2];
  if (nx * cx + ny * cy + nz * cz < 0) { nx = -nx; ny = -ny; nz = -nz; }
  b.triP([p1[0], p1[1], p1[2], nx, ny, nz], [p2[0], p2[1], p2[2], nx, ny, nz], [p3[0], p3[1], p3[2], nx, ny, nz]);
}

const ORIGIN = [0, 0, 0];

/** Hexagonal bipyramid — the classic game crystal (flat facets). */
export function crystalVerts(): Float32Array<ArrayBuffer> {
  const b = new Builder();
  const N = 6;
  const belt = 0.06;                    // waist sits above centre — crystals taper long
  const ring = (i: number): number[] => {
    const a = (i / N) * Math.PI * 2;
    return [Math.cos(a) * 0.32, belt, Math.sin(a) * 0.32];
  };
  for (let i = 0; i < N; i++) {
    const p0 = ring(i), p1 = ring(i + 1);
    face(b, ORIGIN, [0, 0.5, 0], p0, p1);   // long tip up
    face(b, ORIGIN, [0, -0.5, 0], p1, p0);  // short tip down
  }
  return b.build();
}

/** A low-poly boulder: jittered sphere with flat facets (deterministic). */
export function rockVerts(): Float32Array<ArrayBuffer> {
  const b = new Builder();
  const SEG = 7, ROW = 4;
  const pt = (s: number, r: number): number[] => {
    // Poles are SINGLE shared vertices — per-segment y jitter here would
    // split the apex into SEG different points and the top never closes.
    if (r <= 0) return [0, 0.4, 0];
    if (r >= ROW) return [0, -0.36, 0];
    const si = ((s % SEG) + SEG) % SEG;
    const theta = (si / SEG) * Math.PI * 2;
    const phi = (r / ROW) * Math.PI;
    const jitter = 0.34 + rnd(si, r) * 0.16;               // per-vertex radius
    return [
      Math.sin(phi) * Math.cos(theta) * jitter,
      Math.cos(phi) * (0.32 + rnd(r, si) * 0.1),           // slightly squat
      Math.sin(phi) * Math.sin(theta) * jitter,
    ];
  };
  for (let r = 0; r < ROW; r++) {
    for (let s = 0; s < SEG; s++) {
      const a = pt(s, r), c = pt(s + 1, r), d = pt(s + 1, r + 1), e = pt(s, r + 1);
      face(b, ORIGIN, a, c, d);
      face(b, ORIGIN, a, d, e);
    }
  }
  return b.build();
}

/** A ruined column: square plinth, octagonal fluted shaft, square cap. */
export function pillarVerts(): Float32Array<ArrayBuffer> {
  const b = new Builder();
  const box = (x0: number, y0: number, z0: number, x1: number, y1: number, z1: number): void => {
    const mid = [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2];   // each box is convex around ITS centre
    const p = (x: number, y: number, z: number): number[] => [x, y, z];
    face(b, mid, p(x0, y1, z0), p(x1, y1, z0), p(x1, y1, z1)); face(b, mid, p(x0, y1, z0), p(x1, y1, z1), p(x0, y1, z1)); // top
    face(b, mid, p(x0, y0, z0), p(x1, y0, z1), p(x1, y0, z0)); face(b, mid, p(x0, y0, z0), p(x0, y0, z1), p(x1, y0, z1)); // bottom
    face(b, mid, p(x0, y0, z0), p(x1, y0, z0), p(x1, y1, z0)); face(b, mid, p(x0, y0, z0), p(x1, y1, z0), p(x0, y1, z0));
    face(b, mid, p(x1, y0, z1), p(x0, y0, z1), p(x0, y1, z1)); face(b, mid, p(x1, y0, z1), p(x0, y1, z1), p(x1, y1, z1));
    face(b, mid, p(x0, y0, z1), p(x0, y0, z0), p(x0, y1, z0)); face(b, mid, p(x0, y0, z1), p(x0, y1, z0), p(x0, y1, z1));
    face(b, mid, p(x1, y0, z0), p(x1, y0, z1), p(x1, y1, z1)); face(b, mid, p(x1, y0, z0), p(x1, y1, z1), p(x1, y1, z0));
  };
  box(-0.5, -0.5, -0.5, 0.5, -0.38, 0.5);           // plinth
  box(-0.42, 0.38, -0.42, 0.42, 0.5, 0.42);         // cap
  const N = 8;                                       // fluted shaft
  const ring = (i: number, y: number): number[] => {
    const a = ((i % N) / N) * Math.PI * 2 + Math.PI / N;
    const r = 0.3 + (i % 2 === 0 ? 0 : -0.03);       // shallow flutes
    return [Math.cos(a) * r, y, Math.sin(a) * r];
  };
  for (let i = 0; i < N; i++) {
    face(b, ORIGIN, ring(i, -0.38), ring(i + 1, -0.38), ring(i + 1, 0.38));
    face(b, ORIGIN, ring(i, -0.38), ring(i + 1, 0.38), ring(i, 0.38));
  }
  return b.build();
}

/** A tapering four-sided obelisk with a pyramidal tip. */
export function spireVerts(): Float32Array<ArrayBuffer> {
  const b = new Builder();
  const base = 0.26, mid = 0.16, tipY = 0.5, midY = 0.3;
  const sq = (r: number, y: number, i: number): number[] => {
    const a = (i % 4) * Math.PI / 2 + Math.PI / 4;
    return [Math.cos(a) * r * Math.SQRT2, y, Math.sin(a) * r * Math.SQRT2];
  };
  for (let i = 0; i < 4; i++) {
    face(b, ORIGIN, sq(base, -0.5, i), sq(base, -0.5, i + 1), sq(mid, midY, i + 1));   // shaft
    face(b, ORIGIN, sq(base, -0.5, i), sq(mid, midY, i + 1), sq(mid, midY, i));
    face(b, ORIGIN, sq(mid, midY, i), sq(mid, midY, i + 1), [0, tipY, 0]);             // tip
    face(b, ORIGIN, sq(base, -0.5, i + 1), sq(base, -0.5, i), [0, -0.5, 0]);           // underside
  }
  return b.build();
}

/** What registerArt3d hands back: geometry factories + composite spawners. */
export interface Art3d {
  crystal(config?: Mesh3dConfig): Mesh3d;
  rock(config?: Mesh3dConfig): Mesh3d;
  pillar(config?: Mesh3dConfig): Mesh3d;
  spire(config?: Mesh3dConfig): Mesh3d;
  /** Composite: trunk + two canopy cones. Returns the handles (move them together). */
  tree(opts?: { x?: number; z?: number; scale?: number; leaf?: string; trunk?: string }): Mesh3d[];
  /** A deterministic scatter of tilted crystals around a point. */
  crystalCluster(opts?: { x?: number; z?: number; count?: number; color?: string; seed?: number }): Mesh3d[];
}

/**
 * Register the pack's geometries with a world. Every factory shares one
 * instanced draw per shape name, however many meshes you place.
 */
export function registerArt3d(world: World3d): Art3d {
  return {
    crystal: (config = {}) => world.custom('art3d:crystal', crystalVerts, { gloss: 0.85, color: '#7fd4ff', ...config }),
    rock: (config = {}) => world.custom('art3d:rock', rockVerts, { gloss: 0.1, color: '#8a8fa3', ...config }),
    pillar: (config = {}) => world.custom('art3d:pillar', pillarVerts, { gloss: 0.25, color: '#c9c4b8', ...config }),
    spire: (config = {}) => world.custom('art3d:spire', spireVerts, { gloss: 0.5, color: '#5a5f78', ...config }),

    tree(opts = {}) {
      const { x = 0, z = 0, scale = 1, leaf = '#2e7d4f', trunk = '#6b4420' } = opts;
      return [
        world.cylinder({ x, y: 0.9 * scale, z, w: 0.5 * scale, h: 1.8 * scale, d: 0.5 * scale, color: trunk, gloss: 0.05 }),
        world.cone({ x, y: 2.4 * scale, z, w: 2.6 * scale, h: 2.2 * scale, d: 2.6 * scale, color: leaf, gloss: 0.1 }),
        world.cone({ x, y: 3.6 * scale, z, w: 1.8 * scale, h: 1.8 * scale, d: 1.8 * scale, color: leaf, gloss: 0.1 }),
      ];
    },

    crystalCluster(opts = {}) {
      const { x = 0, z = 0, count = 5, color = '#7fd4ff', seed = 1 } = opts;
      const out: Mesh3d[] = [];
      for (let i = 0; i < count; i++) {
        const a = rnd(i, seed) * Math.PI * 2;
        const dist = 0.4 + rnd(i, seed + 9) * 1.6;
        const h = 1.2 + rnd(i, seed + 3) * 2.2;
        out.push(this.crystal({
          x: x + Math.cos(a) * dist,
          y: h * 0.32,
          z: z + Math.sin(a) * dist,
          w: 0.45 * h, h, d: 0.45 * h,
          color,
          pitch: (rnd(i, seed + 5) - 0.5) * 0.5,
          roll: (rnd(i, seed + 7) - 0.5) * 0.5,
          yaw: rnd(i, seed + 11) * Math.PI,
        }));
      }
      return out;
    },
  };
}
